using Aspire.Hosting;
using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluations;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplication? _app;
    private static IChatClient? _chatClient;
    private static ReportingConfiguration? _reportingConfiguration;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await builder.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_RespondsRelevantly()
    {
        await using var scenario = await _reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_RespondsRelevantly));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient!.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Chat_FollowsInstructions()
    {
        await using var scenario = await _reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_FollowsInstructions));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Always respond in exactly one sentence."),
            new(ChatRole.User, "Explain what .NET is.")
        };

        var response = await _chatClient!.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator()
        };

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-results"),
            evaluators: evaluators,
            chatConfiguration: new ChatConfiguration(_chatClient!));
    }
}

